PREFIX patent: <http://data.epo.org/linked-data/def/patent/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX text: <http://jena.apache.org/text#>
SELECT DISTINCT ?publication ?title ?abstract ?date ?application ?filingDate WHERE {
  ?publication text:query (dcterms:abstract "(message AND acknowledgment AND persistent)") ;
     a patent:Publication ; dcterms:abstract ?abstract .
  FILTER(langMatches(lang(?abstract), "en"))
  OPTIONAL { ?publication patent:titleOfInvention ?title . FILTER(langMatches(lang(?title), "en")) }
  OPTIONAL { ?publication patent:publicationDate ?date }
  OPTIONAL { ?publication patent:application ?application .
             OPTIONAL { ?application patent:filingDate ?filingDate } }
} LIMIT 10

